The following example will show basic usage of the VGA ports of a DMPS system. 

  public class ControlSystem : CrestronControlSystem
  {
       //Collection of available VGA ports.
       public List<VgaDviInputPort> VgaPorts = new List<VgaDviInputPort>();
       public Random randomNumber = new Random();

       //Read in VGA ports and subscribe to events in the constructor.
       public ControlSystem()
       {
           if (SupportsSwitcherInputs == false)
           {//Check that switcher inputs are available.
               ErrorLog.Error("No SwitcherInputs Available.");
               return;
           }

           //find all VGA ports for all possible Input types.
           foreach (var input in SwitcherInputs)
           {
               switch (input.CardInputOutputType)
               {
                   case eCardInputOutputType.Dmps3HdmiVgaInput:
                       VgaPorts.Add((input as Card.Dmps3HdmiVgaInput).VgaInputPort);
                       break;
                   case eCardInputOutputType.Dmps3HdmiVgaBncInput:
                       VgaPorts.Add((input as Card.Dmps3HdmiVgaBncInput).VgaInputPort);
                       break;
                   case (eCardInputOutputType.Dmps3VgaInput):
                       VgaPorts.Add((input as Card.Dmps3VgaInput).VgaInputPort);
                       break;
               }
           }

           //This can be done in the loop above.
           foreach (VgaDviInputPort vgaPort in VgaPorts)
           {
               vgaPort.VideoAttributes.AttributeChange += videoAttributeChange;
               vgaPort.VideoControls.ControlChange += videoControlsChange;
           }
           CrestronConsole.AddNewConsoleCommand(ChangeVgaPortSettings, "ChangeVga", "Change some of the settings of the VGA ports.", ConsoleAccessLevelEnum.AccessOperator);
       }

       //Subscription to the Video control feedback of the VGA ports.
       private void videoControlsChange(object sender, GenericEventArgs args)
       {
           var videoControls = sender as VideoControlsEnhanced;

           if (videoControls == null)
               return;
           //Print some information
           switch (args.EventId)
           {
               case (VideoControlsEventIds.BlueFeedbackEventId):
                   CrestronConsole.PrintLine("{0}: Blue = {1}", videoControls.Owner, (short)videoControls.BlueFeedback.UShortValue);
                   break;
               case(VideoControlsEventIds.GreenFeedbackEventId):
                   CrestronConsole.PrintLine("{0}: Green = {1}", videoControls.Owner, (short)videoControls.GreenFeedback.UShortValue);
                   break;
               case(VideoControlsEventIds.RedFeedbackEventId):
                   CrestronConsole.PrintLine("{0}: Red = {1}", videoControls.Owner, (short)videoControls.RedFeedback.UShortValue);
                   break;
               case (VideoControlsEventIds.BrightnessFeedbackEventId):
                   CrestronConsole.PrintLine("{0}: Brightness = {1}", videoControls.Owner, (short)videoControls.BrightnessFeedback.UShortValue);
                   break;
               case(VideoControlsEventIds.ContrastFeedbackEventId):
                   CrestronConsole.PrintLine("{0}: Contrast = {1}", videoControls.Owner, (short)videoControls.ContrastFeedback.UShortValue);
                   break;
           }

       }

       //Method to change a few VGA settings.
       private void ChangeVgaPortSettings(string cmdParameters)
       {
           foreach (var VgaPort in VgaPorts)
           {
               VgaPort.VideoControls.Blue.UShortValue = (ushort) randomNumber.Next(-50, 50);
               VgaPort.VideoControls.Red.UShortValue = (ushort)randomNumber.Next(-50, 50);
               VgaPort.VideoControls.Green.UShortValue = (ushort)randomNumber.Next(-50, 50);
               VgaPort.VideoControls.Brightness.UShortValue = (ushort)randomNumber.Next(-50, 50);
               VgaPort.VideoControls.Contrast.UShortValue = (ushort)randomNumber.Next(-50, 50);
           }
       }

       //Subscription to the video attribute change feedback for the VGA ports.
       private void videoAttributeChange(object sender, GenericEventArgs args)
       {
           var VideoAttributes = sender as VideoAttributesBasic;
           if (VideoAttributes == null)
               return;

           switch(args.EventId)
           {
               case(VideoAttributeEventIds.VerticalResolutionFeedbackEventId):
               case(VideoAttributeEventIds.HorizontalResolutionFeedbackEventId):
               case(VideoAttributeEventIds.FramesPerSecondFeedbackEventId):
                   CrestronConsole.PrintLine("{0}: {1}x{2} @ {3}Hz", VideoAttributes.Owner, VideoAttributes.HorizontalResolutionFeedback.UShortValue, VideoAttributes.VerticalResolutionFeedback.UShortValue, VideoAttributes.FramesPerSecondFeedback.UShortValue);
                   break;
               default:
                   CrestronConsole.PrintLine("AttributeChange: {0} - {1}", VideoAttributes.Owner, args.EventId);
                   break;
           }

       }
   }

The following example will show basic usage of the Digital Mix Output card of a DMPS3-4K-300-C system.

To switch to a DMPS3-4K-250-C, DMPS3-4K-300-C, or DMPS3-4K-350-C system, the appropriate enums should be used:
eDmps34K200COutputs, eDmps34K250COutputs, eDmps34K350COutputs in place of eDmps34K300COutputs.
eDmps34K200CInputs, eDmps34K250CInputs, eDmps34K350CInputs in place of eDmps34K300CInputs.


  public class ControlSystem : CrestronControlSystem
  {
    public Card.Dmps3DigitalMixOutput MixOut;
    public Card.Dmps3DmOutputBackend DmOut;
    public Card.Dmps3HdmiOutputBackend HdmiOut;
    public Card.Dmps3ProgramOutput ProgOut;

    public ControlSystem()
        : base()
    {
        // Find some output cards supporting digital mix output, audio output source..
        MixOut = (Card.Dmps3DigitalMixOutput)SwitcherOutputs[(uint)eDmps34K300COutputs.Mix1];
        DmOut = (Card.Dmps3DmOutputBackend)SwitcherOutputs[(uint)eDmps34K300COutputs.Dm1];
        HdmiOut = (Card.Dmps3HdmiOutputBackend)SwitcherOutputs[(uint)eDmps34K300COutputs.Hdmi1];
        ProgOut = (Card.Dmps3ProgramOutput)SwitcherOutputs[(uint)eDmps34K300COutputs.Program];

        DMOutputChange += new DMOutputEventHandler(ControlSystem_DMOutputChange);
        CrestronConsole.AddNewConsoleCommand(ChangeAudioOutSource, "ChangeAudio", "Change some audio out source settings of some output cards.", ConsoleAccessLevelEnum.AccessOperator);

    }// ControlSystem()

    void ControlSystem_DMOutputChange(Switch device, DMOutputEventArgs args)
    {
        if (args.EventId == DMOutputEventIds.AudioOutEventId || args.EventId == DMOutputEventIds.DigitalMixerAudioSourceFeedBackEventId)
        {
            // Handling the DMOutput events for audio out source change, mixer audio source changes 
            AudioOutSourceChangeHandler(args);
        }
        else
        {
            // Other event handling
        }
    }
    // Method to change audio out source settings
    void ChangeAudioOutSource(string cmdParameters)
    {
        // 1.1. Select a digital mix output card audio source
        MixOut.AudioOutSource = eDmps34KAudioOutSource.Hdmi3;
        // 1.2. Remember our Mix output is eDmps34K300COutputs.Mix1 and mute its master audio.
        MixOut.MasterMuteOn();
        // 1.3. Select a mix output for a DM output (or Hdmi output) and let's select Mix1
        DmOut.AudioOutSourceDevice = eDmps34KAudioOutSourceDevice.DigitalMixer1;
        // 1.4. Now use the mixer selected
        Dmps3AttachableOutputMixer mixer = DmOut.OutputMixer;
        if (mixer != null)
        {
            mixer.MasterMuteOff();
        }
        // 2.1 Let the audio out source of a Hdmi output card follow its input video
        HdmiOut.AudioOutSourceDevice = eDmps34KAudioOutSourceDevice.AudioFollowsVideo;
        // 2.2 Select its input video
        ((DMOutput)HdmiOut).VideoOut = ((DMInput)SwitcherInputs[(uint)eDmps34K300CInputs.Dm2]);
        // 2.3 To stop the audio route, just do
        HdmiOut.AudioOutSourceDevice = eDmps34KAudioOutSourceDevice.NoRoute;

        // 3.1 Select audio out source for a Program output card ( or Codec output, or Aux output)
        ProgOut.AudioOutSource = eDmps34KAudioOutSource.Dm7;
        // 3.2 Or
        ProgOut.AudioOutSource = eDmps34KAudioOutSource.Analog4;

    } //ChangeAudioOutSource()

    // Method to handle audio out source/audio out device changes
    void AudioOutSourceChangeHandler(DMOutputEventArgs args)
    {
        eDmps34K300COutputs who = (eDmps34K300COutputs)args.Number;
        switch (args.EventId)
        {
            case DMOutputEventIds.AudioOutEventId:
            // Find out which output card triggers this event:
            if (who == eDmps34K300COutputs.Program)
            {
               Card.Dmps3ProgramOutput progOut = (Card.Dmps3ProgramOutput)SwitcherOutputs[(uint)eDmps34K300COutputs.Program];
               CrestronConsole.PrintLine("AudioOutSourceChange on {0}, its audio out source: {1}", progOut.ToString(), progOut.AudioOutSourceFeedback.ToString());
            }
            else if (who == eDmps34K300COutputs.Dm1)
            {
               Card.Dmps3DmOutputBackend dmOut = (Card.Dmps3DmOutputBackend)SwitcherOutputs[(uint)eDmps34K300COutputs.Dm1];
               CrestronConsole.PrintLine("AudioOutSourceChange on {0}, its audio out source DEVICE: {1}", dmOut.ToString(), dmOut.AudioOutSourceDeviceFeedback.ToString());
            }
            else if (who == eDmps34K300COutputs.Hdmi1)
            {
               Card.Dmps3HdmiOutputBackend hdmiOut = (Card.Dmps3HdmiOutputBackend)SwitcherOutputs[(uint)eDmps34K300COutputs.Hdmi1];
               CrestronConsole.PrintLine("AudioOutSourceChange on {0}, its audio out source DEVICE: {1}", hdmiOut.ToString(), hdmiOut.AudioOutSourceDeviceFeedback.ToString());

            } 
            else
            {
               CrestronConsole.PrintLine("AudioOutSourceChange: Need more code to find out details.");
            }
            break;
        case DMOutputEventIds.DigitalMixerAudioSourceFeedBackEventId:
           if (who == eDmps34K300COutputs.Mix1)
           {
               Card.Dmps3DigitalMixOutput mixOut = (Card.Dmps3DigitalMixOutput)SwitcherOutputs[(uint)eDmps34K300COutputs.Mix1];
               CrestronConsole.PrintLine("AudioMixerSourceChange on {0}, its audio out source: {1}", mixOut.ToString(), mixOut.AudioOutSourceFeedback.ToString());

           }
           else if (who == eDmps34K300COutputs.Mix2)
           {
               Card.Dmps3DigitalMixOutput mixOut = (Card.Dmps3DigitalMixOutput)SwitcherOutputs[(uint)eDmps34K300COutputs.Mix2];
               CrestronConsole.PrintLine("AudioMixerSourceChange on {0}, its audio out source: {1}", mixOut.ToString(), mixOut.AudioOutSourceFeedback.ToString());
           }
           break;
        default:
           break;
      }
    } // AudioOutSourceChangeHandler()
  }

