// will connect USB from DM Input 7 (eDmps34K200CInputs.Dm1) to DM Output 2 (eDmps34K200COutputs.Dm1) in a DMPS3-4K-200-C.
SwitcherOutput[(uint)eDmps34K200COutputs.Dm1] = SwitcherInput[(uint)eDmps34K200CInputs.Dm1];

// will connect USB from DM Input 7 (eDmps34K250CInputs.Dm1) to DM Output 2 (eDmps34K250COutputs.Dm1) in a DMPS3-4K-250-C.
SwitcherOutput[(uint)eDmps34K250COutputs.Dm1] = SwitcherInput[(uint)eDmps34K250CInputs.Dm1];

// will disconnect USB from DM Output 3 (eDmps34K300COutputs.Dm1) in a DMPS3-4K-300-C.
SwitcherOutput[(uint)eDmps34K300COutputs.Dm1] = null;

// will disconnect USB from DM Output 3 (eDmps34K350COutputs.Dm1) in a DMPS3-4K-350-C.
SwitcherOutput[(uint)eDmps34K350COutputs.Dm1] = null;

// will connect USB from DM Input 6 to DM Output 2 in a DMPS-200-C.
SwitcherOutput[2] = SwitcherInput[6];

// will disconnect USB from DM Output 3 in a DMPS-300-C.
SwitcherOutput[3] = null;

IDmps3OutputMixer outputMixer = output.OutputMixer as IDmps3OutputMixer;
if (output != null)
{
    if (outputMixer.OutputMixerType == eOutputMixerType.Dmps3OutputMixerWithMonoAndStereo)
    {
        // If it supports Mono/Stereo, toggle it.
        Dmps3OutputMixerWithMonoAndStereo OutWithMS = (Dmps3OutputMixerWithMonoAndStereo)output;
        if (OutWithMS.MonoOutputFeedback.BoolValue == true)
            OutWithMS.StereoOutput();
        else
            OutWithMS.MonoOutput();
    }    
}

IOutputMixer output = SwitcherOutputs[1] as IOutputMixer;
if (output != null)
{
    if (output.OutputMixer.OutputMixerType == eOutputMixerType.Dmps3OutputMixerWithMonoAndStereo)
    {
        // If it supports Mono/Stereo, toggle it.
        Dmps3OutputMixerWithMonoAndStereo OutWithMS = (Dmps3OutputMixerWithMonoAndStereo)output;
        if (OutWithMS.MonoOutputFeedback.BoolValue == true)
            OutWithMS.StereoOutput();
        else
            OutWithMS.MonoOutput();
    }    
}

IOutputEqualizer output = SwitcherOutputs[i] as IOutputEqualizer;
if (output != null)
{
   if (output.OutputEqualizer.EqualizerType == eEqualizerType.Dmps3OutputEqualizer)
   {
      // Flip the Limiter bool.
      Dmps3OutputEqualizer OutEq = (Dmps3OutputEqualizer)(output.OutputEqualizer);
      if (OutEq.LimiterEnableFeedback.BoolValue == true)
          OutEq.LimiterDisable();
      else
          OutEq.LimiterEnable();
    }
}

