         public override void InitializeSystem()
         {
             // This should always return   

            SNMP.AddSig(eSigType.Bool, 1, "Digital", eSigIoMask.InputOutputSig);
            SNMP.AddSig(eSigType.Bool, 100, "Digital100", eSigIoMask.InputSigOnly);
            SNMP.AddSig(eSigType.Bool, 1000, "Digital1000", eSigIoMask.OutputSigOnly);

            SNMP.AddSig(eSigType.UShort, 2, "Analog", eSigIoMask.InputOutputSig);
            SNMP.AddSig(eSigType.UShort, 200, "Analog200", eSigIoMask.InputSigOnly);
            SNMP.AddSig(eSigType.UShort, 2000, "Analog2000", eSigIoMask.OutputSigOnly);

            SNMP.AddSig(eSigType.String, 3, "Serial", eSigIoMask.InputOutputSig);
            SNMP.AddSig(eSigType.String, 300, "Serial300", eSigIoMask.InputSigOnly);
            SNMP.AddSig(eSigType.String, 3000, "Serial3000", eSigIoMask.OutputSigOnly);

            SNMP.AddTrap(1, "This is trap number 1");
            SNMP.AddTrap(2, "This is trap number 2");
            SNMP.SigChange += new SNMP.SigEventHandler(SNMP_SigChange);

         } 

         void SNMP_SigChange(SigEventArgs sigEvent)
         {
            CrestronConsole.PrintLine(" Sig change fired for {0} \r\n", sigEvent.Event);
            switch (sigEvent.Event)
            {
                case eSigEvent.BoolChange:
                    CrestronConsole.PrintLine(" bool fired for args {0}. Sig \r\n", sigEvent.Sig.ToString());
                    break;
                case eSigEvent.UShortChange:
                    CrestronConsole.PrintLine(" Ushort fired for args {0} \r\n", sigEvent.Sig.ToString());
                    break;
                case eSigEvent.StringChange:
                    CrestronConsole.PrintLine(" String fired for args {0} \r\n", sigEvent.Sig.ToString());
                    break;
            }
         }

         void SendSNMPSigsAndTraps()
         {
            if (SNMP.UserDefinedUShortSigDetails.Contains(sigNumber))
            {
                SNMP.UserDefinedUShortSigDetails[sigNumber].InputSig.UShortValue = ValueToSend;
            }
            if (SNMP.UserDefinedStringSigDetails.Contains(sigNumber))
            {
                SNMP.UserDefinedStringSigDetails[sigNumber].InputSig.StringValue = ValueToSend;
            }
            if (SNMP.UserDefinedBooleanSigDetails.Contains(sigNumber))
            {
                SNMP.UserDefinedBooleanSigDetails[sigNumber].InputSig.BoolValue = ValueToSend;
            }
            // Now send out some traps
            SNMP.UserDefinedTrapDetails[trapNumber].SendTrap(ValueToSend);
            SNMP.UserDefinedTrapDetails[trapNumber].SendTrap();
         }

