             USB Human Interface Device class.

This class will trigger  and  events.

             The following will show USB how to access the USB Hid ports and register them for use. 

             //Initialize the USB HID of this control system. 
             private void InitializeUSBHID()
             {
                CrestronConsole.ConsoleCommandResponse("Supports USB HID {0}\r\n", SupportsUsbHid);
                CrestronConsole.ConsoleCommandResponse("Number of USB HID Ports {0}\r\n", NumberOfUsbHids);

                if (SupportsUsbHid)
                {
                    foreach (var usbHid in UsbHids)
                    {
                        CrestronConsole.ConsoleCommandResponse("\tHID Port {0}\r\n", usbHid.ID);

                        if (firsttime)
                        {
                            usbHid.BaseEvent += UsbHidOnBaseEvent;
                            usbHid.OnlineStatusChange += UsbHidOnOnlineStatusChange;
                            //Set to some testing value for now.
                            usbHid.OutputReport.StringValue = "12";
                            usbHid.FeatureReport.StringValue = "56";
                        }

                        CrestronConsole.ConsoleCommandResponse("\t\t Online: {0}\r\n", usbHid.IsOnline);

                        if (usbHid.Registered)
                            CrestronConsole.ConsoleCommandResponse("\t\t UnRegister: {0}\r\n", usbHid.UnRegister());
                        else
                            CrestronConsole.ConsoleCommandResponse("\t\t Register: {0}\r\n", usbHid.Register());

                    }
                    firsttime = false;
                }
             }

             //Triggered when the USB HID is connected and online with the system.
             private void UsbHidOnOnlineStatusChange(GenericBase currentDevice, OnlineOfflineEventArgs args)
             {
                CrestronConsole.PrintLine("{0} went {1}", currentDevice, args.DeviceOnLine? "Online":"Offline");
             }

             //Base events for information received from the USB HID.
             private void UsbHidOnBaseEvent(GenericBase device, BaseEventArgs args)
             {
                var usbHid = device as UsbHid;
                if (usbHid == null)
                    return;

                switch (args.EventId)
                {
                    case(UsbHid.CountryCodeFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Country Code: {1}", usbHid, usbHid.CountryCodeFeedback);
                        break;
                    case(UsbHid.ManufacturerFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Manufacturer: {1}", usbHid, usbHid.ManufacturerFeedback.StringValue);
                        break;
                    case (UsbHid.ProductFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Product: {1}", usbHid, usbHid.ProductFeedback.StringValue);
                        break;//SerialNumberFeedbackEventId
                    case (UsbHid.SerialNumberFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Serial Number: {1}", usbHid, usbHid.SerialNumberFeedback.StringValue);
                        break;
                    case(UsbHid.FeatureReportFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Feature Report {1}", usbHid, usbHid.FeatureReportFeedback.StringValue);
                        break;
                    case(UsbHid.InputReportFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Input Report {1}", usbHid, usbHid.InputReportFeedback.StringValue);
                        break;
                    case (UsbHid.ReportDescriptorFeedbackEventId):
                        CrestronConsole.PrintLine("{0} Report Descriptor = {1}", usbHid, usbHid.ReportDescriptorFeedback.StringValue);
                        break;
                }
             }

example.code:
public class ControlSystem : CrestronControlSystem
{
    GlsOirLclCCn _occSensor;
    Xpanel _xpanel;

    public ControlSystem()
    {
        // Register for incoming signals from XiO
        ControllerXioCloudRoomSlotDevice.BaseEvent += CloudRoom_PropertyChangeEventHandler;

        // Register for XiO connection status change
        ControllerXioCloudRoomSlotDevice.OnlineStatusChange += CloudRoom_OnlineStatusChange;

        _occSensor = new GlsOirLclCCn(0x17, this);
        _occSensor.BaseEvent += OccSensor_PropertyChangeEventHandler;

        _xpanel = new Xpanel(0x05, this);
    }

    public override void InitializeSystem()
    {
        // Register the CloudRoom slot with XiO; by default all signals on the slot are registered with XiO
        // Signals may be passed here to exclude their registration with XiO
        if (ControllerXioCloudRoomSlotDevice.Register(ControllerXioCloudRoomSlotDevice.Occupied, ControllerXioCloudRoomSlotDevice.Vacant) == eDeviceRegistrationUnRegistrationResponse.Success)
        {
            // AlertsFeedback may be sent at any time
            ControllerXioCloudRoomSlotDevice.AlertsFeedback.StringValue = "Program has started";
        }

        _occSensor.Register();
        _xpanel.Register();
    }

    private void CloudRoom_OnlineStatusChange(GenericBase currentDevice, OnlineOfflineEventArgs args)
    {
        const uint XioOnlineStateJoin = 1;

        _xpanel.BooleanInput[XioOnlineStateJoin].BoolValue = args.DeviceOnLine;

        // Set current source feedback with enum value
        ControllerXioCloudRoomSlotDevice.CurrentSourceFeedback.Value = XioCloudRoomSlot.eCurrentSource.Laptop1;
    }

    private void CloudRoom_PropertyChangeEventHandler(GenericBase device, BaseEventArgs args)
    {
        // Handle all events which come in from XiO

        switch (args.EventId)
        {
            case XioCloudRoomSlot.SystemPowerOnEventId:
                TurnSystemPowerOn();
                break;
            case XioCloudRoomSlot.SystemPowerOffEventId:
                TurnSystemPowerOff();
                break;
            case XioCloudRoomSlot.DisplayPowerOnEventId:
                TurnDisplayPowerOn();
                break;
            case XioCloudRoomSlot.DisplayPowerOffEventId:
                TurnDisplayPowerOff();
                break;
            case XioCloudRoomSlot.OccupiedEventId:
                HandleOccupiedEvent(ControllerXioCloudRoomSlotDevice.Occupied.BoolValue);
                break;
            case XioCloudRoomSlot.VacantEventId:
                HandleVacantEvent(ControllerXioCloudRoomSlotDevice.Vacant.BoolValue);
                break;
            case XioCloudRoomSlot.RoomNameEventId:
                HandleRoomNameEvent(ControllerXioCloudRoomSlotDevice.RoomName.StringValue);
                break;
            case XioCloudRoomSlot.MaintenanceModeEventId:
                HandleMaintenanceModeEvent(ControllerXioCloudRoomSlotDevice.MaintenanceMode.BoolValue);
                break;
            case XioCloudRoomSlot.SystemCheckEventId:
                RunSystemCheck();
                break;
        }
    }

    private void TurnSystemPowerOn()
    {
        // Send system power state to XiO
        ControllerXioCloudRoomSlotDevice.SystemPowerFeedback.BoolValue = true;
    }

    private void TurnSystemPowerOff()
    {
        // Send system power state to XiO
        ControllerXioCloudRoomSlotDevice.SystemPowerFeedback.BoolValue = false;
    }

    private void TurnDisplayPowerOn()
    {
        // Send display power state to XiO
        ControllerXioCloudRoomSlotDevice.DisplayPowerFeedback.BoolValue = true;
    }

    private void TurnDisplayPowerOff()
    {
        // Send display power state to XiO
        ControllerXioCloudRoomSlotDevice.DisplayPowerFeedback.BoolValue = false;
    }

    private void HandleOccupiedEvent(bool value)
    {
        const uint OccupiedStateJoin = 10;

        _xpanel.BooleanInput[OccupiedStateJoin].BoolValue = value;
    }

    private void HandleVacantEvent(bool value)
    {
        const uint VacantStateJoin = 11;

        _xpanel.BooleanInput[VacantStateJoin].BoolValue = value;
    }

    private void HandleRoomNameEvent(string value)
    {
        const uint RoomNameJoin = 12;

        _xpanel.StringInput[RoomNameJoin].StringValue = value;
    }

    private void HandleMaintenanceModeEvent(bool value)
    {
        const uint MaintenanceModeJoin = 13;

        if (value)
        {
            _xpanel.StringInput[MaintenanceModeJoin].StringValue = "Room is in maintenance mode";
        }
        else
        {
            _xpanel.StringInput[MaintenanceModeJoin].StringValue = "";
        }
    }

    private void RunSystemCheck()
    {
        ControllerXioCloudRoomSlotDevice.SystemCheckStateFeedback.Value = XioCloudRoomSlot.eSystemCheckState.Running;

        if (_occSensor.IsOnline)
        {
            ControllerXioCloudRoomSlotDevice.SystemCheckStateFeedback.Value = XioCloudRoomSlot.eSystemCheckState.Success;
        }
        else
        {
            // SystemCheckMessageFeedback may be sent to provide details about system check
            ControllerXioCloudRoomSlotDevice.SystemCheckMessageFeedback.StringValue = "Occupancy sensor offline";
            ControllerXioCloudRoomSlotDevice.SystemCheckStateFeedback.Value = XioCloudRoomSlot.eSystemCheckState.Error;
        }
    }

    public void OccSensor_PropertyChangeEventHandler(GenericBase device, BaseEventArgs args)
    {
        if (args.EventId == GlsOccupancySensorBase.RoomOccupiedFeedbackEventId)
        {
            // Send occupancy state to XiO
            ControllerXioCloudRoomSlotDevice.OccupiedFeedback.BoolValue = _occSensor.OccupancyDetectedFeedback.BoolValue;
        }
    }
}

public class XioCloudSpaceExample : CrestronControlSystem
{
    GlsOirLclCCn _occSensor;
    Xpanel _xpanel;

    public XioCloudSpaceExample()
    {
        // Register for incoming signals from XiO
        ControllerXioCloudSpaceSlotDevice.BaseEvent += CloudSpace_PropertyChangeEventHandler;

        // Register for XiO connection status change
        ControllerXioCloudSpaceSlotDevice.OnlineStatusChange += CloudSpace_OnlineStatusChange;

        _occSensor = new GlsOirLclCCn(0x17, this);
        _occSensor.BaseEvent += OccSensor_PropertyChangeEventHandler;

        _xpanel = new Xpanel(0x05, this);
    }

    public override void InitializeSystem()
    {
        // Register the CloudSpace slot with XiO; by default all signals on the slot are registered with XiO
        // Signals may be passed here to exclude their registration with XiO
        if (ControllerXioCloudSpaceSlotDevice.Register(ControllerXioCloudSpaceSlotDevice.Occupied, ControllerXioCloudSpaceSlotDevice.Vacant) == eDeviceRegistrationUnRegistrationResponse.Success)
        {
            // AlertsFeedback may be sent at any time
            ControllerXioCloudSpaceSlotDevice.AlertsFeedback.StringValue = "Program has started";
        }

        _occSensor.Register();
        _xpanel.Register();
    }

    private void CloudSpace_OnlineStatusChange(GenericBase currentDevice, OnlineOfflineEventArgs args)
    {
        const uint XioOnlineStateJoin = 1;

        _xpanel.BooleanInput[XioOnlineStateJoin].BoolValue = args.DeviceOnLine;

        // Set current source feedback with enum value
        ControllerXioCloudSpaceSlotDevice.CurrentSourceFeedback.Value = eCurrentSource.Laptop1;
    }

    private void CloudSpace_PropertyChangeEventHandler(GenericBase device, BaseEventArgs args)
    {
        // Handle all events which come in from XiO

        switch (args.EventId)
        {
            case XioCloudSpaceEventIds.SystemPowerOnEventId:
                TurnSystemPowerOn();
                break;
            case XioCloudSpaceEventIds.SystemPowerOffEventId:
                TurnSystemPowerOff();
                break;
            case XioCloudSpaceEventIds.DisplayPowerOnEventId:
                TurnDisplayPowerOn();
                break;
            case XioCloudSpaceEventIds.DisplayPowerOffEventId:
                TurnDisplayPowerOff();
                break;
            case XioCloudSpaceEventIds.OccupiedEventId:
                HandleOccupiedEvent(ControllerXioCloudSpaceSlotDevice.Occupied.BoolValue);
                break;
            case XioCloudSpaceEventIds.VacantEventId:
                HandleVacantEvent(ControllerXioCloudSpaceSlotDevice.Vacant.BoolValue);
                break;
            case XioCloudSpaceEventIds.SpaceNameEventId:
                HandleSpaceNameEvent(ControllerXioCloudSpaceSlotDevice.MetaData.SpaceName.StringValue);
                break;
            case XioCloudSpaceEventIds.MaintenanceModeEventId:
                HandleMaintenanceModeEvent(ControllerXioCloudSpaceSlotDevice.MaintenanceMode.BoolValue);
                break;
            case XioCloudSpaceEventIds.SystemCheckEventId:
                RunSystemCheck();
                break;

           case XioCloudSpaceEventIds.VolumeLevelEventId:
               HandleVolumeLevelEvent(ControllerXioCloudSpaceSlotDevice.Volume.VolumeLevel.UShortValue);
               break;
           case XioCloudSpaceEventIds.LightSceneEventId:
               HandleLightSceneEvent(args.Index);
               break;
       }
    }

   private void TurnSystemPowerOn()
    {
        // Send system power state to XiO
        ControllerXioCloudSpaceSlotDevice.SystemPowerFeedback.BoolValue = true;
    }

    private void TurnSystemPowerOff()
    {
        // Send system power state to XiO
        ControllerXioCloudSpaceSlotDevice.SystemPowerFeedback.BoolValue = false;
    }

    private void TurnDisplayPowerOn()
    {
        // Send display power state to XiO
        ControllerXioCloudSpaceSlotDevice.DisplayPowerFeedback.BoolValue = true;
    }

    private void TurnDisplayPowerOff()
    {
        // Send display power state to XiO
        ControllerXioCloudSpaceSlotDevice.DisplayPowerFeedback.BoolValue = false;
    }

    private void HandleOccupiedEvent(bool value)
    {
        const uint OccupiedStateJoin = 10;

        _xpanel.BooleanInput[OccupiedStateJoin].BoolValue = value;
    }

    private void HandleVacantEvent(bool value)
    {
        const uint VacantStateJoin = 11;

        _xpanel.BooleanInput[VacantStateJoin].BoolValue = value;
    }

    private void HandleSpaceNameEvent(string value)
    {
        const uint RoomNameJoin = 12;

        _xpanel.StringInput[RoomNameJoin].StringValue = value;
    }

    private void HandleMaintenanceModeEvent(bool value)
    {
        const uint MaintenanceModeJoin = 13;

        if (value)
        {
            _xpanel.StringInput[MaintenanceModeJoin].StringValue = "Room is in maintenance mode";
        }
        else
        {
            _xpanel.StringInput[MaintenanceModeJoin].StringValue = "";
        }
   }

   private void HandleVolumeLevelEvent(ushort value)
   {
       const uint VolumeLevelJoin = 14;

       _xpanel.UShortInput[VolumeLevelJoin].UShortValue = value;
   }

   private void HandleLightSceneEvent(int index)
   {
       switch (index)
       {
           case 2:
               break;
           case 3:
               break;
           case 4:
               break;
           case 5:
               break;
           default:
               // Unsupported index
               break;
       }
   }

   private void RunSystemCheck()
    {
        ControllerXioCloudSpaceSlotDevice.SystemCheckStateFeedback.Value = eSystemCheckState.Running;

        if (_occSensor.IsOnline)
        {
            ControllerXioCloudSpaceSlotDevice.SystemCheckStateFeedback.Value = eSystemCheckState.Success;
        }
        else
        {
            // SystemCheckMessageFeedback may be sent to provide details about system check
            ControllerXioCloudSpaceSlotDevice.SystemCheckMessageFeedback.StringValue = "Occupancy sensor offline";
            ControllerXioCloudSpaceSlotDevice.SystemCheckStateFeedback.Value = eSystemCheckState.Error;
        }
    }

    public void OccSensor_PropertyChangeEventHandler(GenericBase device, BaseEventArgs args)
    {
        if (args.EventId == GlsOccupancySensorBase.RoomOccupiedFeedbackEventId)
        {
            // Send occupancy state to XiO
            ControllerXioCloudSpaceSlotDevice.OccupiedFeedback.BoolValue = _occSensor.OccupancyDetectedFeedback.BoolValue;
        }
    }
}

